#define DT_DRV_COMPAT zephyr_i2c_emul

#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/devicetree.h>
#include <zephyr/sys/util.h>

struct i2c_emul_data {
	const struct device *i2c;
	struct i2c_emul_config cfg;
};

static int i2c_emul_transfer(const struct device *dev, struct i2c_msg *msgs,
			     uint8_t num_msgs, uint16_t slave_address)
{
	struct i2c_emul_data *data = dev->data;

	return i2c_emul_transfer_internal(data->i2c, msgs, num_msgs, slave_address,
					  &data->cfg);
}

static const struct i2c_driver_api i2c_emul_api = {
	.transfer = i2c_emul_transfer,
};

static int i2c_emul_init(const struct device *dev)
{
	struct i2c_emul_data *data = dev->data;

	if (!device_is_ready(data->i2c)) {
		return -ENODEV;
	}

	return 0;
}

#define I2C_EMUL_DEFINE(inst)                                                  \
	static struct i2c_emul_data i2c_emul_data_##inst = {                       \
		.i2c = DEVICE_DT_GET(DT_INST_PARENT(inst)),                            \
		.cfg = {                                                               \
			.addr = DT_INST_REG_ADDR(inst),                                    \
			.emul = DT_INST_EMUL_API(inst),                                    \
		},                                                                     \
	};                                                                         \
	DEVICE_DT_INST_DEFINE(inst, i2c_emul_init, NULL,                           \
			      &i2c_emul_data_##inst, NULL, POST_KERNEL,            \
			      CONFIG_I2C_EMUL_INIT_PRIORITY, &i2c_emul_api);

DT_INST_FOREACH_STATUS_OKAY(I2C_EMUL_DEFINE)
